const CACHE_NAME="todo-app-v1",DATA_CACHE_NAME="todo-app-data-v1";self.addEventListener("install",(e=>{console.log("Installing Custom Cache Manager"),e.waitUntil(caches.open(CACHE_NAME).then((e=>e.addAll(["./","./index.html","./manifest.json","./icons/icon-192x192.png","./icons/icon-512x512.png","./offline.html"]))))})),self.addEventListener("activate",(e=>{console.log("Activating Custom Cache Manager"),e.waitUntil(caches.keys().then((e=>Promise.all(e.map((e=>{if(e!==CACHE_NAME&&e!==DATA_CACHE_NAME)return console.log("Deleting old cache:",e),caches.delete(e)}))))))})),self.addEventListener("fetch",(e=>{e.request.url.includes("/backup-localStorage")&&(console.log("Handling backup request:",e.request.url),e.respondWith(caches.open(DATA_CACHE_NAME).then((t=>fetch(e.request).then((n=>(t.put(e.request,n.clone()),n))).catch((()=>t.match(e.request)))))))}));